<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;">  --oidc-audience</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">此伺服器的</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> audienc</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#F47067;"> \\</span></span>
