<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;">  --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> ./.env</span><span style="--shiki-light:#005CC5;--shiki-dark:#F47067;"> \\</span></span>
